# 1. Number of handles
puts "1. Total number of handles: #{handles.length}"

# 2. Shortest handle
shortest_handle = handles.min_by { |handle| handle.length }
puts "2. Shortest handle: #{shortest_handle}"

# 3. Handles with 5 characters (excluding @)
count_five_characters = 0
i = 0
while i < handles.length
  count_five_characters += 1 if handles[i][1..-1].length == 5
  i += 1
end
puts "3. Number of handles with exactly 5 characters: #{count_five_characters}"

# 4. Handles starting with a capital letter
count_capital = 0
i = 0
while i < handles.length
  first_char = handles[i][1]
  count_capital += 1 if ('A'..'Z').include?(first_char)
  i += 1
end
puts "4. Number of handles starting with a capital letter: #{count_capital}"

# 5. Sort handles alphabetically
sorted_handles = handles.sort
puts "5. First 10 handles in alphabetical order: #{sorted_handles.first(10)}"

# 6. Sort handles by length
sorted_by_length = handles.sort_by { |handle| handle.length }
puts "6. First 10 shortest handles: #{sorted_by_length.first(10)}"

# 7. Index of @epenser
index_epenser = handles.index("@epenser")
puts "7. Index of @epenser: #{index_epenser}"

# 8. Distribution of handles by length (excluding '@')
length_distribution = Hash.new(0)
i = 0
while i < handles.length
  size = handles[i][1..-1].length
  length_distribution[size] += 1
  i += 1
end

puts "8. Distribution of handles by length:"
length_distribution.sort.each do |length, count|
  puts " - #{length} characters: #{count} handles"
end
